from datetime import date, timedelta

class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self._books = set()            # book ids in the library (including borrowed ones)
        self._borrowed = {}            # book_id -> (user, borrow_day)
        self._user_book = {}           # user -> book_id
        self._fines = {}               # user -> unpaid fine amount

    def add_book(self, book_id: str) -> None:
        if book_id in self._books:
            raise ValueError(f"Book {book_id!r} already exists")
        self._books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self._books:
            raise ValueError(f"Unknown book {book_id!r}")
        if book_id in self._borrowed:
            raise ValueError(f"Book {book_id!r} is already borrowed")
        if user in self._user_book:
            raise ValueError(f"User {user!r} already holds a book")
        if self._fines.get(user, 0.0) > 0:
            # Users with unpaid fines may still borrow but only one at a time.
            # This is already ensured by the single-book rule above.
            pass
        self._borrowed[book_id] = (user, day)
        self._user_book[user] = book_id

    def return_book(self, user: str, book_id: str, day: date) -> float:
        info = self._borrowed.get(book_id)
        if info is None or info[0] != user:
            raise ValueError(f"User {user!r} has not borrowed book {book_id!r}")
        _, borrow_day = info
        due_day = borrow_day + timedelta(days=self.loan_days)
        fine = 0.0
        if day > due_day:
            late_days = 0
            d = due_day + timedelta(days=1)
            while d <= day:
                if d.weekday() < 5:  # Monday=0 ... Friday=4
                    late_days += 1
                d += timedelta(days=1)
            fine = late_days * self.daily_fine
        del self._borrowed[book_id]
        del self._user_book[user]
        if fine > 0:
            self._fines[user] = self._fines.get(user, 0.0) + fine
        return fine

    def unpaid_fines(self, user: str) -> float:
        return self._fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        self._fines[user] = 0.0
```

